"""Dispatch to per-module configuration tabs."""

from __future__ import annotations

from collections.abc import Callable
import streamlit as st

from optichub.dashboard.node_modules.defaults import merged_config
from optichub.dashboard.node_modules.module_overview import module_can_stop
from optichub.dashboard.node_modules.tabs.command_runner import tab_command_runner
from optichub.dashboard.node_modules.tabs.prefect_and_process import (
    tab_lsm_process_server,
    tab_oct_process_server,
    tab_prefect_worker,
)
from optichub.dashboard.node_modules.tabs.primocache import tab_primocache_monitor
from optichub.dashboard.node_modules.tabs.redis_workers import (
    tab_redis_queue_burst_worker,
    tab_redis_queue_worker,
)
from optichub.dashboard.node_modules.tabs.watchers import tab_lsm_watcher, tab_oct_watcher
from optichub.grpc_client import ModuleInfo


def render_module_tab(
    module: str,
    *,
    host: str,
    port: int,
    info: ModuleInfo | None,
    key: Callable[[str], str],
) -> None:
    cfg = merged_config(module, info)
    state = info.state if info else "not loaded"
    running = info is not None and state == "running"
    can_stop = module_can_stop(info)

    st.subheader(module.replace("_", " "))
    st.caption(f"State: **{state}**")
    if info and info.error:
        st.warning(info.error)

    if module == "command_runner":
        tab_command_runner(host, port, info, cfg, running, can_stop, key)
    elif module == "prefect_worker":
        tab_prefect_worker(host, port, info, cfg, running, can_stop, key)
    elif module == "lsm_process_server":
        tab_lsm_process_server(host, port, info, cfg, running, can_stop, key)
    elif module == "oct_process_server":
        tab_oct_process_server(host, port, info, cfg, running, can_stop, key)
    elif module == "redis_queue_worker":
        tab_redis_queue_worker(host, port, info, cfg, running, can_stop, key)
    elif module == "redis_queue_burst_worker":
        tab_redis_queue_burst_worker(host, port, info, cfg, running, can_stop, key)
    elif module == "lsm_watcher":
        tab_lsm_watcher(host, port, info, cfg, running, can_stop, key)
    elif module == "oct_watcher":
        tab_oct_watcher(host, port, info, cfg, running, can_stop, key)
    elif module == "primocache_monitor":
        tab_primocache_monitor(host, port, info, cfg, running, can_stop, key)
